const parentManifestBytes=gunzipSync(Buffer.from('','base64'),{maxOutputLength:30000});
const parentInventoryBytes=gunzipSync(Buffer.from('','base64'),{maxOutputLength:100000});
async function inputs(){const sourceBytes={};for(const r of I.sources){const historical=N12_CHANGED_SOURCE_WITNESSES[r.path];if(historical){assert.equal(historical.bytes,r.bytes);assert.equal(historical.sha256,r.sha256);sourceBytes[r.path]=gunzipSync(Buffer.from(historical.gzip_base64,'base64'),{maxOutputLength:historical.bytes});assert.equal(sourceBytes[r.path].length,r.bytes);assert.equal(sha(sourceBytes[r.path]),r.sha256);}else sourceBytes[r.path]=await fs.readFile(new URL('../../'+r.path,import.meta.url));}sourceBytes[I.native.source]=await fs.readFile(new URL('../../'+I.native.source,import.meta.url));return{parentManifestBytes:Buffer.from(parentManifestBytes),parentInventoryBytes:Buffer.from(parentInventoryBytes),sourceBytes};}
test('closed17 source inputs plus native212 derive77/41/30 and full61-parent/inventory inverse',async()=>{
 const b=await inputs(),result=deriveLocalWooRead212SourceContract(b),before=JSON.parse(parentManifestBytes),after=result.manifest;
 assert.equal(I.sources.length,17);assert.equal(sha(parentManifestBytes),I.parent_manifest_sha256);assert.equal(after.files.length,77);assert.equal(after.files.filter(r=>r.role==='runtime-source').length,41);assert.equal(after.native_contract.sql_graph.length,30);
 assert.deepEqual(result.inverseManifestBytes,parentManifestBytes);assert.deepEqual(result.inverseInventoryBytes,parentInventoryBytes);
 assert.equal(result.changes.filter(r=>r.before).length,2);assert.deepEqual(result.changes.filter(r=>r.before).map(r=>r.after.path),['server/app.ts','server/ordinary-local-runtime.ts']);
 for(const old of before.files.filter(r=>!['server/app.ts','server/ordinary-local-runtime.ts','contract/source-inventory.json'].includes(r.path)))assert.deepEqual(after.files.find(r=>r.path===old.path),old,'whole retained '+old.path);
 const expected=structuredClone(before.native_contract);expected.sql_graph.push({id:I.native.id,path:I.native.path,sha256:I.native.sha256});assert.deepEqual(after.native_contract,expected);assert.deepEqual(after.adapter_contract,before.adapter_contract);
 const inventory=JSON.parse(result.inventoryBytes),oldInventory=JSON.parse(parentInventoryBytes);inventory.source_graph.pop();assert.deepEqual(inventory,oldInventory,'only inventory source_graph appended');
 assert.equal(result.source_compilation_proven,true);for(const key of ['native_certification','application_activation','business_acceptance'])assert.equal(result[key],false);
});
test('every bound core/routes/worker/UI/CLI/operator/shared source rejects changed bytes',async()=>{const b=await inputs();for(const name of Object.keys(b.sourceBytes)){const sourceBytes={...b.sourceBytes,[name]:Buffer.concat([b.sourceBytes[name],Buffer.from(' ')] )};assert.throws(()=>deriveLocalWooRead212SourceContract({...b,sourceBytes}),undefined,name);}});
test('missing/extra source inputs and modified parent/inventory cannot be silently approved',async()=>{const b=await inputs();for(const k of ['parentManifestBytes','parentInventoryBytes'])assert.throws(()=>deriveLocalWooRead212SourceContract({...b,[k]:Buffer.concat([b[k],Buffer.from(' ')] )}));const missing={...b.sourceBytes};delete missing['server/local-woo-read-lane.ts'];assert.throws(()=>deriveLocalWooRead212SourceContract({...b,sourceBytes:missing}));assert.throws(()=>deriveLocalWooRead212SourceContract({...b,sourceBytes:{...b.sourceBytes,'server/arbitrary.ts':Buffer.from('')}}));});
test('derivations do not mutate caller bytes and each returned manifest is independent',async()=>{const b=await inputs(),saved=structuredClone(b),first=deriveLocalWooRead212SourceContract(b);first.manifest.native_contract.sql_graph.pop();first.changes[0].before.path='bad';first.inventoryBytes.fill(0);const second=deriveLocalWooRead212SourceContract(b);assert.equal(second.manifest.native_contract.sql_graph.length,30);assert.deepEqual(second.inverseManifestBytes,parentManifestBytes);for(const k of ['parentManifestBytes','parentInventoryBytes'])assert.deepEqual(b[k],Buffer.from(saved[k]));for(const k of Object.keys(b.sourceBytes))assert.deepEqual(b.sourceBytes[k],Buffer.from(saved.sourceBytes[k]));assert(Object.isFrozen(I));assert(Object.isFrozen(I.sources));assert(I.sources.every(Object.isFrozen));});
const validatorMirrors=['portable-release.mjs','emitted-release.mjs','ordinary177-contract.mjs','resource-definitions.mjs','resource-io.mjs','resource-format209.mjs'];
async function checkerFixture(t){const root=await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(),'read212-source-check-')));t.after(()=>fs.rm(root,{recursive:true,force:true}));const b=await inputs(),d=deriveLocalWooRead212SourceContract(b),base='shared/large-import-dependencies/pim-large-import173-business-traversal-ui/';async function put(name,bytes){await fs.mkdir(path.dirname(path.join(root,name)),{recursive:true});await fs.writeFile(path.join(root,name),bytes);}
 for(const r of I.sources)await put(r.path,b.sourceBytes[r.path]);await put(I.native.source,b.sourceBytes[I.native.source]);
 const compatibility=Buffer.from('{"controlled":"source-check-only"}');await put(base+'ordinary177-contract.json',compatibility);
 for(const name of validatorMirrors)await put(base+name,await fs.readFile(new URL(name,import.meta.url)));
 const full={files:[...I.sources.map(r=>({path:r.path,role:r.role,bytes:r.bytes,sha256:r.sha256})),{path:I.native.path,role:'native-sql',bytes:I.native.bytes,sha256:I.native.sha256},{path:'contract/ordinary177.json',role:'compatibility-contract',bytes:compatibility.length,sha256:sha(compatibility)}],native_contract:{compatibility:{path:'contract/ordinary177.json'}}};
 // N12 also pinned the validator mirror resource-format209.mjs (7742 B). 6cb235e and later changed
 // that validator, and the current checker requires the mirror to equal its own tool, so the whole
 // historical N12 roster is refused by today's checker. Keep that refusal explicit and check every
 // other N12 member; the mirror itself stays enforced by the validator loop.
 const mirror=I.sources.filter(r=>r.path.startsWith(base)&&validatorMirrors.includes(r.path.slice(base.length)));assert.deepEqual(mirror.map(r=>[r.path,r.bytes]),[[base+'resource-format209.mjs',7742]]);
 assert.notEqual(sha(await fs.readFile(new URL('resource-format209.mjs',import.meta.url))),mirror[0].sha256);await assert.rejects(assertProjectContractMembers(root,full),/source-contract-runtime-(size|drift)/);
 const manifest={...full,files:full.files.filter(r=>r.path!==mirror[0].path)};return{root,manifest,put};}
test('actual project checker binds historical N12 core/routes/UI/operator and native bytes before any emit',async t=>{const f=await checkerFixture(t);await assertProjectContractMembers(f.root,f.manifest);for(const name of ['server/local-woo-read-lane.ts','server/local-woo-read-lane-routes.ts','server/local-woo-read-worker.ts','web/local-woo-read-lanes.tsx','tools/local/operator.mjs']){const p=path.join(f.root,name),old=await fs.readFile(p);await fs.appendFile(p,'\n// unreviewed');await assert.rejects(assertProjectContractMembers(f.root,f.manifest),/source-contract-runtime/);await fs.writeFile(p,old);}await fs.appendFile(path.join(f.root,I.native.source),' ');await assert.rejects(assertProjectContractMembers(f.root,f.manifest),/source-contract-native/);});
test('actual project checker refuses missing transitive module or mismatched validator mirror',async t=>{const f=await checkerFixture(t),worker=path.join(f.root,'server/local-woo-read-worker.ts'),original=await fs.readFile(worker);await fs.unlink(worker);await assert.rejects(assertProjectContractMembers(f.root,f.manifest),{code:'ENOENT'});await fs.writeFile(worker,original);await fs.appendFile(path.join(f.root,'shared/large-import-dependencies/pim-large-import173-business-traversal-ui/portable-release.mjs'),'\n// changed validator');await assert.rejects(assertProjectContractMembers(f.root,f.manifest),/source-contract-validator-version-drift/);});
test('file publisher refuses nested output before generation; no publication/SQL/runtime in test',async t=>{const f=await checkerFixture(t),output=path.join(f.root,'forbidden');await assert.rejects(prepareLocalWooRead212SourceContract({parentRoot:f.root,projectRoot:f.root,outputRoot:output}),/212 output outside inputs/);await assert.rejects(fs.lstat(output),{code:'ENOENT'});});
